{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MapleMonk.Zouk_Exotel_Calling_Report AS WITH Exotel_Data AS ( SELECT `To`, `From`, CASE WHEN \'08660829967\' IN (`From`, `To`) THEN \'Nahida Khan\' WHEN \'08756103170\' IN (`From`, `To`) THEN \'Dolly Mourya\' WHEN \'06307948515\' IN (`From`, `To`) THEN \'Suryansh Mishra\' WHEN \'07058210559\' IN (`From`, `To`) THEN \'Neeha Khan\' WHEN \'09067403769\' IN (`From`, `To`) THEN \'Mahima Waghmare\' WHEN \'07710905246\' IN (`From`, `To`) THEN \'Injila Ansari\' WHEN \'08454915895\' IN (`From`, `To`) THEN \'Subra Haldar\' WHEN \'07941057138\' IN (`From`, `To`) THEN \'Store Phone Support\' WHEN \'08069454521\' IN (`From`, `To`) THEN \'Website Phone Support\' WHEN \'08425019026\' IN (`From`, `To`) THEN \'Madhuri\' WHEN \'09620405284\' IN (`From`, `To`) THEN \'Shruthi\' WHEN \'08169548367\' IN (`From`, `To`) THEN \'Hudanaaz Khan\' WHEN \'09028021577\' IN (`From`, `To`) THEN \'Hima Bharde\' WHEN LOWER(Direction) like \'%inbound%\' THEN `To` WHEN LOWER(Direction) like \'%outbound%\' THEN `From` ELSE NULL END AS Agent_Name, CAST(Status AS STRING) AS Status, CAST(Duration AS INT64) AS Duration, CAST(Direction AS STRING) AS Direction, CASE WHEN Direction like \'inbound\' THEN `From` WHEN Direction like \'%outbound%\' THEN `To` END AS Customer_Number, JSON_VALUE(Details, \'$.Leg1Status\') AS Leg1_Status, JSON_VALUE(Details, \'$.Leg2Status\') AS Leg2_Status, StartTime AS Start_Time, EndTime AS End_Time, CASE WHEN PhoneNumber = \'08069454521\' AND EXTRACT(HOUR FROM PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', StartTime)) BETWEEN 12 AND 17 THEN \'Working Hour\' WHEN PhoneNumber = \'07941057138\' AND EXTRACT(HOUR FROM PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', StartTime)) BETWEEN 10 AND 18 THEN \'Working Hour\' ELSE \'Extra\' END AS Time_Category, DATE(DateCreated) AS Date_Created, DateUpdated AS Date_Updated, CAST(PhoneNumber AS STRING) AS Phone_Number, CASE WHEN PhoneNumber = \'07941057138\' THEN \'Store\' WHEN PhoneNumber = \'08069454521\' THEN \'Website\' END AS Type FROM `MapleMonk.Zouk_bulk_calls` ) SELECT * FROM Exotel_Data ; CREATE OR REPLACE TABLE Maplemonk.Zouk_Exotel_Unresolved_Call_Report AS WITH Inbound_Unanswered AS ( SELECT Customer_Number, PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', Start_Time) AS Call_Time, Agent_Name AS Initial_Agent, Leg2_Status, Type, Direction FROM `MapleMonk.Zouk_Exotel_Calling_Report` WHERE Direction = \'inbound\' AND Time_Category = \'Working Hour\' AND LOWER(Leg2_Status) IN (\'no-answer\', \'failed\', \'busy\', \'canceled\') AND Customer_Number IS NOT NULL ), Followup_Completed AS ( SELECT Customer_Number, PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', Start_Time) AS Call_Time, Agent_Name AS Recovered_By_Agent, Direction, Type, Leg2_Status FROM `MapleMonk.Zouk_Exotel_Calling_Report` WHERE LOWER(Leg2_Status) = \'completed\' AND Customer_Number IS NOT NULL ), Resolved_Status AS ( SELECT u.Customer_Number, u.Call_Time AS First_Unanswered_Time, u.Initial_Agent, u.Type, f.Call_Time AS Recovery_Time, f.Direction AS Recovery_Direction, f.Recovered_By_Agent, CASE WHEN LOWER(f.Direction) = \'inbound\' THEN \'Customer_Retried\' WHEN LOWER(f.Direction) LIKE \'outbound%\' THEN \'Agent_Called_Back\' ELSE \'Unknown\' END AS Recovery_Type, \'Yes\' AS Resolved FROM Inbound_Unanswered u JOIN Followup_Completed f ON u.Customer_Number = f.Customer_Number AND f.Call_Time > u.Call_Time QUALIFY ROW_NUMBER() OVER (PARTITION BY u.Customer_Number, u.Call_Time ORDER BY f.Call_Time ASC) = 1 ), Final AS ( SELECT u.Customer_Number, u.Call_Time AS First_Unanswered_Date, u.Type, COALESCE(r.Recovery_Time, NULL) AS Resolved_Date, COALESCE(r.Resolved, \'No\') AS Resolved, COALESCE(r.Recovery_Type, NULL) AS Resolved_Type, COALESCE(r.Recovered_By_Agent, NULL) AS Resolved_By_Agent, u.Initial_Agent FROM Inbound_Unanswered u LEFT JOIN Resolved_Status r ON u.Customer_Number = r.Customer_Number AND u.Call_Time = r.First_Unanswered_Time ) SELECT * FROM Final ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

